# Initially generated by GitHub Copilot.
"""Create a PowerPoint deck from slide order in a script.md table."""

from __future__ import annotations

import argparse
import pathlib
import re

from PIL import Image
from pptx import Presentation
from pptx.util import Inches

_NESTED_IMAGE_LINK_RE = re.compile(r"\[\s*!\[[^\]]*\]\(([^)]+)\)\s*\]\(([^)]+)\)")
_IMAGE_RE = re.compile(r"!\[[^\]]*\]\(([^)]+)\)")


def _looks_like_separator_cell(cell: str) -> bool:
    return bool(cell) and set(cell) <= {"-", ":", " "}


def _row_image_cell_lines(script_text: str) -> list[tuple[int, str]]:
    lines: list[tuple[int, str]] = []
    for line_number, raw_line in enumerate(script_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line.startswith("|"):
            continue
        cells = [c.strip() for c in line.strip("|").split("|")]
        if not cells:
            continue
        image_cell = cells[0]
        if image_cell.lower() == "image":
            continue
        if _looks_like_separator_cell(image_cell):
            continue
        lines.append((line_number, image_cell))
    return lines


def _slide_rel_path_from_image_cell(image_cell: str, line_number: int) -> pathlib.Path:
    nested_match = _NESTED_IMAGE_LINK_RE.search(image_cell)
    if nested_match:
        # In rows like [![thumb](img/thumb-foo.png)](img/slide-foo.png),
        # use the outer link target directly.
        return pathlib.Path(nested_match.group(2).strip())

    image_match = _IMAGE_RE.search(image_cell)
    if image_match is None:
        raise SystemExit(
            f"No markdown image found in script row at line {line_number}."
        )

    image_rel = pathlib.Path(image_match.group(1).strip())
    if image_rel.name.startswith("slide-"):
        return image_rel
    if image_rel.name.startswith("thumb-"):
        return image_rel.with_name(image_rel.name.replace("thumb-", "slide-", 1))

    raise SystemExit(
        "Cannot infer slide image path from script row at line "
        f"{line_number}: expected image name to start with 'thumb-' or 'slide-'."
    )


def slide_paths_from_script(script_path: pathlib.Path) -> list[pathlib.Path]:
    script_text = script_path.read_text(encoding="utf-8")
    image_rows = _row_image_cell_lines(script_text)
    if not image_rows:
        raise SystemExit(f"No slide rows found in {script_path}")

    script_dir = script_path.parent
    slide_paths: list[pathlib.Path] = []
    for line_number, image_cell in image_rows:
        slide_rel = _slide_rel_path_from_image_cell(image_cell, line_number)
        slide_path = script_dir / slide_rel
        if not slide_path.is_file():
            raise SystemExit(
                f"Missing slide image referenced by {script_path}:{line_number}: {slide_path}"
            )
        slide_paths.append(slide_path)

    return slide_paths


def _fit_inside(
    img_w: int, img_h: int, box_w: int, box_h: int
) -> tuple[int, int, int, int]:
    scale = min(box_w / img_w, box_h / img_h)
    out_w = int(round(img_w * scale))
    out_h = int(round(img_h * scale))
    left = (box_w - out_w) // 2
    top = (box_h - out_h) // 2
    return left, top, out_w, out_h


def build_pptx(slide_paths: list[pathlib.Path], output_path: pathlib.Path) -> None:
    prs = Presentation()
    prs.slide_width = Inches(13.333333)
    prs.slide_height = Inches(7.5)
    blank = prs.slide_layouts[6]

    slide_w = int(prs.slide_width)
    slide_h = int(prs.slide_height)

    for slide_path in slide_paths:
        slide = prs.slides.add_slide(blank)
        with Image.open(slide_path) as im:
            img_w, img_h = im.size
        left, top, width, height = _fit_inside(img_w, img_h, slide_w, slide_h)
        slide.shapes.add_picture(
            str(slide_path),
            left,
            top,
            width=width,
            height=height,
        )

    output_path.parent.mkdir(parents=True, exist_ok=True)
    prs.save(str(output_path))
    print(f"Saved {output_path} ({len(slide_paths)} slides)")


def cmd_make_pptx(args: argparse.Namespace) -> None:
    slide_paths = slide_paths_from_script(args.script)
    build_pptx(slide_paths, args.output)
